{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyPpOQIYboCyzgPirbU8viy5"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"colab":{"base_uri":"https://localhost:8080/","height":821},"id":"613xgPaQ11ov","executionInfo":{"status":"error","timestamp":1788717036735,"user_tz":180,"elapsed":430,"user":{"displayName":"Paulo De Barros","userId":"02717175820811500479"}},"outputId":"ee2282ba-1850-44f5-d411-6695306f111d"},"outputs":[{"output_type":"error","ename":"ModuleNotFoundError","evalue":"No module named 'supabase'","traceback":["\u001b[0;31m---------------------------------------------------------------------------\u001b[0m","\u001b[0;31mModuleNotFoundError\u001b[0m                       Traceback (most recent call last)","\u001b[0;32m/tmp/ipykernel_5816/2812003770.py\u001b[0m in \u001b[0;36m<cell line: 0>\u001b[0;34m()\u001b[0m\n\u001b[1;32m     15\u001b[0m )\n\u001b[1;32m     16\u001b[0m \u001b[0;34m\u001b[0m\u001b[0m\n\u001b[0;32m---> 17\u001b[0;31m \u001b[0;32mfrom\u001b[0m \u001b[0msupabase\u001b[0m \u001b[0;32mimport\u001b[0m \u001b[0mcreate_client\u001b[0m\u001b[0;34m\u001b[0m\u001b[0;34m\u001b[0m\u001b[0m\n\u001b[0m\u001b[1;32m     18\u001b[0m \u001b[0;34m\u001b[0m\u001b[0m\n\u001b[1;32m     19\u001b[0m \u001b[0;34m\u001b[0m\u001b[0m\n","\u001b[0;31mModuleNotFoundError\u001b[0m: No module named 'supabase'","","\u001b[0;31m---------------------------------------------------------------------------\u001b[0;32m\nNOTE: If your import is failing due to a missing package, you can\nmanually install dependencies using either !pip or !apt.\n\nTo view examples of installing some common dependencies, click the\n\"Open Examples\" button below.\n\u001b[0;31m---------------------------------------------------------------------------\u001b[0m\n"],"errorDetails":{"actions":[{"action":"open_url","actionText":"Open Examples","url":"/notebooks/snippets/importing_libraries.ipynb"}]}}],"source":["\n","import os\n","from functools import wraps\n","from decimal import Decimal, InvalidOperation\n","from urllib.parse import urlparse\n","\n","from flask import (\n","    Flask,\n","    render_template,\n","    request,\n","    redirect,\n","    url_for,\n","    session,\n","    flash,\n","    jsonify\n",")\n","\n","from supabase import create_client\n","\n","\n","# ==========================================================\n","# CONFIGURAÇÃO\n","# ==========================================================\n","\n","app = Flask(__name__)\n","\n","app.secret_key = os.environ.get(\n","    \"FLASK_SECRET_KEY\",\n","    \"chave-temporaria-trocar-em-producao\"\n",")\n","\n","SUPABASE_URL = os.environ[\"SUPABASE_URL\"]\n","SUPABASE_KEY = os.environ[\"SUPABASE_KEY\"]\n","\n","supabase = create_client(\n","    SUPABASE_URL,\n","    SUPABASE_KEY\n",")\n","\n","ADMIN_USER = os.environ.get(\n","    \"ADMIN_USER\",\n","    \"admin\"\n",")\n","\n","ADMIN_PASSWORD = os.environ.get(\n","    \"ADMIN_PASSWORD\",\n","    \"admin\"\n",")\n","\n","\n","# ==========================================================\n","# FUNÇÕES AUXILIARES\n","# ==========================================================\n","\n","def texto_formulario(nome, padrao=\"\"):\n","    \"\"\"\n","    Obtém um campo do formulário sem retornar None.\n","    \"\"\"\n","    return request.form.get(nome, padrao).strip()\n","\n","\n","def converter_preco(valor):\n","    \"\"\"\n","    Converte preços como:\n","    99\n","    99.90\n","    99,90\n","\n","    Retorna None quando o campo estiver vazio.\n","    \"\"\"\n","\n","    valor = str(valor or \"\").strip()\n","\n","    if not valor:\n","        return None\n","\n","    valor = valor.replace(\"R$\", \"\")\n","    valor = valor.replace(\".\", \"\")\n","    valor = valor.replace(\",\", \".\")\n","\n","    try:\n","        preco = Decimal(valor)\n","\n","        if preco < 0:\n","            raise ValueError(\"O preço não pode ser negativo.\")\n","\n","        return float(preco)\n","\n","    except (InvalidOperation, ValueError):\n","        raise ValueError(\"Digite um preço válido.\")\n","\n","\n","def converter_categoria(valor):\n","    \"\"\"\n","    Converte o ID da categoria para inteiro.\n","    \"\"\"\n","    valor = str(valor or \"\").strip()\n","\n","    if not valor:\n","        return None\n","\n","    try:\n","        return int(valor)\n","\n","    except ValueError:\n","        raise ValueError(\"Categoria inválida.\")\n","\n","\n","def checkbox_ativo(nome):\n","    \"\"\"\n","    Retorna True quando o checkbox estiver marcado.\n","    \"\"\"\n","    return request.form.get(nome) == \"on\"\n","\n","\n","def url_valida(url):\n","    \"\"\"\n","    Valida URLs de imagem e links de afiliado.\n","    \"\"\"\n","    if not url:\n","        return True\n","\n","    try:\n","        resultado = urlparse(url)\n","\n","        return resultado.scheme in (\n","            \"http\",\n","            \"https\"\n","        ) and bool(resultado.netloc)\n","\n","    except Exception:\n","        return False\n","\n","\n","def montar_dados_produto():\n","    \"\"\"\n","    Monta os dados enviados para o Supabase.\n","    \"\"\"\n","\n","    nome = texto_formulario(\"nome\")\n","\n","    if not nome:\n","        raise ValueError(\"O nome do produto é obrigatório.\")\n","\n","    imagem_url = texto_formulario(\"imagem_url\")\n","    link_afiliado = texto_formulario(\"link_afiliado\")\n","\n","    if not url_valida(imagem_url):\n","        raise ValueError(\n","            \"A URL da imagem precisa começar com http:// ou https://.\"\n","        )\n","\n","    if not url_valida(link_afiliado):\n","        raise ValueError(\n","            \"O link de afiliado precisa ser uma URL válida.\"\n","        )\n","\n","    dados = {\n","        \"nome\": nome,\n","\n","        \"descricao\": texto_formulario(\n","            \"descricao\"\n","        ),\n","\n","        \"categoria_id\": converter_categoria(\n","            request.form.get(\"categoria_id\")\n","        ),\n","\n","        \"preco\": converter_preco(\n","            request.form.get(\"preco\")\n","        ),\n","\n","        \"imagem_url\": imagem_url,\n","\n","        \"link_afiliado\": link_afiliado,\n","\n","        \"plataforma\": texto_formulario(\n","            \"plataforma\",\n","            \"Amazon\"\n","        ),\n","\n","        \"ativo\": checkbox_ativo(\n","            \"ativo\"\n","        ),\n","\n","        \"destaque\": checkbox_ativo(\n","            \"destaque\"\n","        )\n","    }\n","\n","    return dados\n","\n","\n","def buscar_categorias(apenas_ativas=False):\n","    \"\"\"\n","    Busca as categorias cadastradas.\n","    \"\"\"\n","\n","    consulta = (\n","        supabase\n","        .table(\"categorias\")\n","        .select(\"*\")\n","    )\n","\n","    if apenas_ativas:\n","        consulta = consulta.eq(\n","            \"ativo\",\n","            True\n","        )\n","\n","    return (\n","        consulta\n","        .order(\"nome\")\n","        .execute()\n","        .data or []\n","    )\n","\n","\n","def buscar_produto(produto_id):\n","    \"\"\"\n","    Busca um produto pelo ID.\n","    \"\"\"\n","\n","    resultado = (\n","        supabase\n","        .table(\"produtos\")\n","        .select(\"*\")\n","        .eq(\"id\", produto_id)\n","        .limit(1)\n","        .execute()\n","    )\n","\n","    if not resultado.data:\n","        return None\n","\n","    return resultado.data[0]\n","\n","\n","def buscar_todos_produtos():\n","    \"\"\"\n","    Busca todos os produtos.\n","    \"\"\"\n","\n","    return (\n","        supabase\n","        .table(\"produtos\")\n","        .select(\"*\")\n","        .order(\"id\", desc=True)\n","        .execute()\n","        .data or []\n","    )\n","\n","\n","def calcular_estatisticas(produtos):\n","    \"\"\"\n","    Calcula estatísticas para o painel administrativo.\n","    \"\"\"\n","\n","    total = len(produtos)\n","\n","    ativos = sum(\n","        1 for produto in produtos\n","        if produto.get(\"ativo\") is True\n","    )\n","\n","    inativos = total - ativos\n","\n","    destaques = sum(\n","        1 for produto in produtos\n","        if produto.get(\"destaque\") is True\n","    )\n","\n","    sem_imagem = sum(\n","        1 for produto in produtos\n","        if not produto.get(\"imagem_url\")\n","    )\n","\n","    sem_link = sum(\n","        1 for produto in produtos\n","        if not produto.get(\"link_afiliado\")\n","    )\n","\n","    sem_descricao = sum(\n","        1 for produto in produtos\n","        if not produto.get(\"descricao\")\n","    )\n","\n","    produtos_incompletos = sum(\n","        1\n","        for produto in produtos\n","        if (\n","            not produto.get(\"imagem_url\")\n","            or not produto.get(\"link_afiliado\")\n","            or not produto.get(\"descricao\")\n","        )\n","    )\n","\n","    return {\n","        \"total\": total,\n","        \"ativos\": ativos,\n","        \"inativos\": inativos,\n","        \"destaques\": destaques,\n","        \"sem_imagem\": sem_imagem,\n","        \"sem_link\": sem_link,\n","        \"sem_descricao\": sem_descricao,\n","        \"produtos_incompletos\": produtos_incompletos\n","    }\n","\n","\n","# ==========================================================\n","# PROTEÇÃO ADMINISTRATIVA\n","# ==========================================================\n","\n","def admin_required(func):\n","\n","    @wraps(func)\n","    def wrapper(*args, **kwargs):\n","\n","        if not session.get(\"admin_logado\"):\n","            flash(\n","                \"Faça login para acessar o painel.\",\n","                \"warning\"\n","            )\n","\n","            return redirect(\n","                url_for(\"login\")\n","            )\n","\n","        return func(*args, **kwargs)\n","\n","    return wrapper\n","\n","\n","# ==========================================================\n","# PÁGINA PRINCIPAL\n","# ==========================================================\n","\n","@app.route(\"/\")\n","def index():\n","\n","    try:\n","        produtos_resultado = (\n","            supabase\n","            .table(\"produtos\")\n","            .select(\"*\")\n","            .eq(\"ativo\", True)\n","            .order(\"destaque\", desc=True)\n","            .order(\"id\", desc=True)\n","            .execute()\n","        )\n","\n","        categorias_resultado = (\n","            supabase\n","            .table(\"categorias\")\n","            .select(\"*\")\n","            .eq(\"ativo\", True)\n","            .order(\"nome\")\n","            .execute()\n","        )\n","\n","        return render_template(\n","            \"index.html\",\n","            produtos=produtos_resultado.data or [],\n","            categorias=categorias_resultado.data or []\n","        )\n","\n","    except Exception:\n","        flash(\n","            \"Não foi possível carregar os produtos.\",\n","            \"danger\"\n","        )\n","\n","        return render_template(\n","            \"index.html\",\n","            produtos=[],\n","            categorias=[]\n","        )\n","\n","\n","# ==========================================================\n","# LISTAGEM DE PRODUTOS\n","# ==========================================================\n","\n","@app.route(\"/produtos\")\n","def produtos():\n","\n","    busca = request.args.get(\n","        \"q\",\n","        \"\"\n","    ).strip()\n","\n","    categoria_id = request.args.get(\n","        \"categoria\",\n","        \"\"\n","    ).strip()\n","\n","    try:\n","        consulta = (\n","            supabase\n","            .table(\"produtos\")\n","            .select(\"*\")\n","            .eq(\"ativo\", True)\n","        )\n","\n","        if busca:\n","            consulta = consulta.ilike(\n","                \"nome\",\n","                f\"%{busca}%\"\n","            )\n","\n","        if categoria_id:\n","            try:\n","                consulta = consulta.eq(\n","                    \"categoria_id\",\n","                    int(categoria_id)\n","                )\n","\n","            except ValueError:\n","                pass\n","\n","        resultado = (\n","            consulta\n","            .order(\"destaque\", desc=True)\n","            .order(\"id\", desc=True)\n","            .execute()\n","        )\n","\n","        categorias = buscar_categorias(\n","            apenas_ativas=True\n","        )\n","\n","        return render_template(\n","            \"produtos.html\",\n","            produtos=resultado.data or [],\n","            categorias=categorias,\n","            busca=busca,\n","            categoria_selecionada=categoria_id\n","        )\n","\n","    except Exception:\n","        flash(\n","            \"Erro ao buscar produtos.\",\n","            \"danger\"\n","        )\n","\n","        return render_template(\n","            \"produtos.html\",\n","            produtos=[],\n","            categorias=[],\n","            busca=busca,\n","            categoria_selecionada=categoria_id\n","        )\n","\n","\n","# ==========================================================\n","# LOGIN\n","# ==========================================================\n","\n","@app.route(\n","    \"/login\",\n","    methods=[\"GET\", \"POST\"]\n",")\n","def login():\n","\n","    if session.get(\"admin_logado\"):\n","        return redirect(\n","            url_for(\"admin\")\n","        )\n","\n","    erro = None\n","\n","    if request.method == \"POST\":\n","\n","        usuario = texto_formulario(\n","            \"usuario\"\n","        )\n","\n","        senha = request.form.get(\n","            \"senha\",\n","            \"\"\n","        )\n","\n","        if (\n","            usuario == ADMIN_USER\n","            and senha == ADMIN_PASSWORD\n","        ):\n","\n","            session.clear()\n","\n","            session[\"admin_logado\"] = True\n","\n","            flash(\n","                \"Login realizado com sucesso.\",\n","                \"success\"\n","            )\n","\n","            return redirect(\n","                url_for(\"admin\")\n","            )\n","\n","        erro = \"Usuário ou senha incorretos.\"\n","\n","    return render_template(\n","        \"login.html\",\n","        erro=erro\n","    )\n","\n","\n","# ==========================================================\n","# LOGOUT\n","# ==========================================================\n","\n","@app.route(\"/logout\")\n","def logout():\n","\n","    session.clear()\n","\n","    flash(\n","        \"Você saiu do painel.\",\n","        \"info\"\n","    )\n","\n","    return redirect(\n","        url_for(\"index\")\n","    )\n","\n","\n","# ==========================================================\n","# PAINEL ADMINISTRATIVO\n","# ==========================================================\n","\n","@app.route(\"/admin\")\n","@admin_required\n","def admin():\n","\n","    try:\n","        produtos = buscar_todos_produtos()\n","\n","        categorias = buscar_categorias()\n","\n","        estatisticas = calcular_estatisticas(\n","            produtos\n","        )\n","\n","        busca = request.args.get(\n","            \"q\",\n","            \"\"\n","        ).strip()\n","\n","        categoria_id = request.args.get(\n","            \"categoria\",\n","            \"\"\n","        ).strip()\n","\n","        produtos_filtrados = produtos\n","\n","        if busca:\n","            produtos_filtrados = [\n","                produto\n","                for produto in produtos_filtrados\n","                if busca.lower()\n","                in produto.get(\n","                    \"nome\",\n","                    \"\"\n","                ).lower()\n","            ]\n","\n","        if categoria_id:\n","            try:\n","                categoria_numero = int(\n","                    categoria_id\n","                )\n","\n","                produtos_filtrados = [\n","                    produto\n","                    for produto in produtos_filtrados\n","                    if produto.get(\n","                        \"categoria_id\"\n","                    ) == categoria_numero\n","                ]\n","\n","            except ValueError:\n","                pass\n","\n","        return render_template(\n","            \"admin.html\",\n","            produtos=produtos_filtrados,\n","            categorias=categorias,\n","            estatisticas=estatisticas,\n","            busca=busca,\n","            categoria_selecionada=categoria_id\n","        )\n","\n","    except Exception:\n","        flash(\n","            \"Erro ao carregar o painel.\",\n","            \"danger\"\n","        )\n","\n","        return render_template(\n","            \"admin.html\",\n","            produtos=[],\n","            categorias=[],\n","            estatisticas={\n","                \"total\": 0,\n","                \"ativos\": 0,\n","                \"inativos\": 0,\n","                \"destaques\": 0,\n","                \"sem_imagem\": 0,\n","                \"sem_link\": 0,\n","                \"sem_descricao\": 0,\n","                \"produtos_incompletos\": 0\n","            },\n","            busca=\"\",\n","            categoria_selecionada=\"\"\n","        )\n","\n","\n","# ==========================================================\n","# NOVO PRODUTO\n","# ==========================================================\n","\n","@app.route(\n","    \"/admin/produto/novo\",\n","    methods=[\"GET\", \"POST\"]\n",")\n","@admin_required\n","def novo_produto():\n","\n","    categorias = buscar_categorias(\n","        apenas_ativas=True\n","    )\n","\n","    if request.method == \"POST\":\n","\n","        try:\n","            dados = montar_dados_produto()\n","\n","            (\n","                supabase\n","                .table(\"produtos\")\n","                .insert(dados)\n","                .execute()\n","            )\n","\n","            flash(\n","                \"Produto cadastrado com sucesso.\",\n","                \"success\"\n","            )\n","\n","            return redirect(\n","                url_for(\"admin\")\n","            )\n","\n","        except Exception as erro:\n","            flash(\n","                f\"Erro ao cadastrar produto: {erro}\",\n","                \"danger\"\n","            )\n","\n","    return render_template(\n","        \"produto_form.html\",\n","        produto=None,\n","        categorias=categorias\n","    )\n","\n","\n","# ==========================================================\n","# EDITAR PRODUTO\n","# ==========================================================\n","\n","@app.route(\n","    \"/admin/produto/<int:produto_id>/editar\",\n","    methods=[\"GET\", \"POST\"]\n",")\n","@admin_required\n","def editar_produto(produto_id):\n","\n","    produto = buscar_produto(\n","        produto_id\n","    )\n","\n","    if not produto:\n","        flash(\n","            \"Produto não encontrado.\",\n","            \"danger\"\n","        )\n","\n","        return redirect(\n","            url_for(\"admin\")\n","        )\n","\n","    categorias = buscar_categorias(\n","        apenas_ativas=True\n","    )\n","\n","    if request.method == \"POST\":\n","\n","        try:\n","            dados = montar_dados_produto()\n","\n","            (\n","                supabase\n","                .table(\"produtos\")\n","                .update(dados)\n","                .eq(\"id\", produto_id)\n","                .execute()\n","            )\n","\n","            flash(\n","                \"Produto atualizado com sucesso.\",\n","                \"success\"\n","            )\n","\n","            return redirect(\n","                url_for(\"admin\")\n","            )\n","\n","        except Exception as erro:\n","            flash(\n","                f\"Erro ao atualizar produto: {erro}\",\n","                \"danger\"\n","            )\n","\n","    return render_template(\n","        \"produto_form.html\",\n","        produto=produto,\n","        categorias=categorias\n","    )\n","\n","\n","# ==========================================================\n","# DUPLICAR PRODUTO\n","# ==========================================================\n","\n","@app.route(\n","    \"/admin/produto/<int:produto_id>/duplicar\",\n","    methods=[\"POST\"]\n",")\n","@admin_required\n","def duplicar_produto(produto_id):\n","\n","    produto = buscar_produto(\n","        produto_id\n","    )\n","\n","    if not produto:\n","        flash(\n","            \"Produto não encontrado.\",\n","            \"danger\"\n","        )\n","\n","        return redirect(\n","            url_for(\"admin\")\n","        )\n","\n","    dados = {\n","        \"nome\": f\"{produto.get('nome', '')} - Cópia\",\n","\n","        \"descricao\": produto.get(\n","            \"descricao\"\n","        ),\n","\n","        \"categoria_id\": produto.get(\n","            \"categoria_id\"\n","        ),\n","\n","        \"preco\": produto.get(\n","            \"preco\"\n","        ),\n","\n","        \"imagem_url\": produto.get(\n","            \"imagem_url\"\n","        ),\n","\n","        \"link_afiliado\": produto.get(\n","            \"link_afiliado\"\n","        ),\n","\n","        \"plataforma\": produto.get(\n","            \"plataforma\",\n","            \"Amazon\"\n","        ),\n","\n","        \"ativo\": False,\n","\n","        \"destaque\": False\n","    }\n","\n","    try:\n","        (\n","            supabase\n","            .table(\"produtos\")\n","            .insert(dados)\n","            .execute()\n","        )\n","\n","        flash(\n","            \"Produto duplicado. A cópia foi criada desativada.\",\n","            \"success\"\n","        )\n","\n","    except Exception as erro:\n","        flash(\n","            f\"Erro ao duplicar produto: {erro}\",\n","            \"danger\"\n","        )\n","\n","    return redirect(\n","        url_for(\"admin\")\n","    )\n","\n","\n","# ==========================================================\n","# ATIVAR OU DESATIVAR PRODUTO\n","# ==========================================================\n","\n","@app.route(\n","    \"/admin/produto/<int:produto_id>/alternar\",\n","    methods=[\"POST\"]\n",")\n","@admin_required\n","def alternar_produto(produto_id):\n","\n","    produto = buscar_produto(\n","        produto_id\n","    )\n","\n","    if not produto:\n","        flash(\n","            \"Produto não encontrado.\",\n","            \"danger\"\n","        )\n","\n","        return redirect(\n","            url_for(\"admin\")\n","        )\n","\n","    novo_status = not bool(\n","        produto.get(\"ativo\")\n","    )\n","\n","    try:\n","        (\n","            supabase\n","            .table(\"produtos\")\n","            .update({\n","                \"ativo\": novo_status\n","            })\n","            .eq(\"id\", produto_id)\n","            .execute()\n","        )\n","\n","        if novo_status:\n","            mensagem = \"Produto ativado.\"\n","        else:\n","            mensagem = \"Produto desativado.\"\n","\n","        flash(\n","            mensagem,\n","            \"success\"\n","        )\n","\n","    except Exception as erro:\n","        flash(\n","            f\"Erro ao alterar produto: {erro}\",\n","            \"danger\"\n","        )\n","\n","    return redirect(\n","        url_for(\"admin\")\n","    )\n","\n","\n","# ==========================================================\n","# DESATIVAR PRODUTO\n","# ==========================================================\n","\n","@app.route(\n","    \"/admin/produto/<int:produto_id>/desativar\",\n","    methods=[\"POST\"]\n",")\n","@admin_required\n","def desativar_produto(produto_id):\n","\n","    try:\n","        (\n","            supabase\n","            .table(\"produtos\")\n","            .update({\n","                \"ativo\": False\n","            })\n","            .eq(\"id\", produto_id)\n","            .execute()\n","        )\n","\n","        flash(\n","            \"Produto desativado.\",\n","            \"success\"\n","        )\n","\n","    except Exception as erro:\n","        flash(\n","            f\"Erro ao desativar produto: {erro}\",\n","            \"danger\"\n","        )\n","\n","    return redirect(\n","        url_for(\"admin\")\n","    )\n","\n","\n","# ==========================================================\n","# ALTERNAR DESTAQUE\n","# ==========================================================\n","\n","@app.route(\n","    \"/admin/produto/<int:produto_id>/destaque\",\n","    methods=[\"POST\"]\n",")\n","@admin_required\n","def alternar_destaque(produto_id):\n","\n","    produto = buscar_produto(\n","        produto_id\n","    )\n","\n","    if not produto:\n","        flash(\n","            \"Produto não encontrado.\",\n","            \"danger\"\n","        )\n","\n","        return redirect(\n","            url_for(\"admin\")\n","        )\n","\n","    novo_destaque = not bool(\n","        produto.get(\"destaque\")\n","    )\n","\n","    try:\n","        (\n","            supabase\n","            .table(\"produtos\")\n","            .update({\n","                \"destaque\": novo_destaque\n","            })\n","            .eq(\"id\", produto_id)\n","            .execute()\n","        )\n","\n","        flash(\n","            \"Destaque do produto atualizado.\",\n","            \"success\"\n","        )\n","\n","    except Exception as erro:\n","        flash(\n","            f\"Erro ao alterar destaque: {erro}\",\n","            \"danger\"\n","        )\n","\n","    return redirect(\n","        url_for(\"admin\")\n","    )\n","\n","\n","# ==========================================================\n","# API DE PRODUTOS\n","# ==========================================================\n","\n","@app.route(\"/api/produtos\")\n","def api_produtos():\n","\n","    try:\n","        produtos = (\n","            supabase\n","            .table(\"produtos\")\n","            .select(\"*\")\n","            .eq(\"ativo\", True)\n","            .order(\"destaque\", desc=True)\n","            .order(\"id\", desc=True)\n","            .execute()\n","        )\n","\n","        return jsonify({\n","            \"status\": \"sucesso\",\n","            \"total\": len(produtos.data or []),\n","            \"produtos\": produtos.data or []\n","        })\n","\n","    except Exception as erro:\n","\n","        return jsonify({\n","            \"status\": \"erro\",\n","            \"mensagem\": str(erro)\n","        }), 500\n","\n","\n","# ==========================================================\n","# HEALTH CHECK\n","# ==========================================================\n","\n","@app.route(\"/health\")\n","def health():\n","\n","    try:\n","\n","        supabase.table(\n","            \"produtos\"\n","        ).select(\n","            \"id\"\n","        ).limit(\n","            1\n","        ).execute()\n","\n","        return {\n","            \"status\": \"online\",\n","            \"supabase\": \"conectado\"\n","        }\n","\n","    except Exception as erro:\n","\n","        return {\n","            \"status\": \"erro\",\n","            \"supabase\": \"desconectado\",\n","            \"erro\": str(erro)\n","        }, 500\n","\n","\n","# ==========================================================\n","# EXECUÇÃO LOCAL\n","# ==========================================================\n","\n","if __name__ == \"__main__\":\n","\n","    port = int(\n","        os.environ.get(\n","            \"PORT\",\n","            5000\n","        )\n","    )\n","\n","    app.run(\n","        host=\"0.0.0.0\",\n","        port=port,\n","        debug=False\n","    )"]}]}